                t1, t2 = solve_2_by_2([y1[1], -y2[1], y2[0]-y1[0]], [z1[1], -z2[1], z2[0]-z1[0]])
                if abs(t1*x1[1] - t2*x2[1] - x2[0] + x1[0]) < EPS:
                    return (x1[0]+t1*x1[1], y1[0]+t1*y1[1], z1[0]+t1*z1[1]), t2
                else:
                    return None
            except:
