def counter(a, m, d):
    modulo = 1000000007
    res = [0, ] * (2*m)
    res[0] = 1
    shift = 1
    for pos in range(len(a), 0, -1):
        ptype = pos % 2
        cur = int(a[pos-1])
        tres = [0, ] * (2*m)
        for i in range(10):
            if ptype==1 and i == d:
                continue
            if ptype==0 and i != d:
                continue
            k = (i * shift) % m
            for j in range(m):
                if i < cur:
                    tres[k*2+0] += res[j*2+0]
                    if tres[k*2+0] >= modulo:
                        tres[k*2+0] -= modulo
                    tres[k*2+0] += res[j*2+1]
                    if tres[k*2+0] >= modulo:
                        tres[k*2+0] -= modulo
                elif i == cur:
                    tres[k*2+0] += res[j*2+0]
                    if tres[k*2+0] >= modulo:
                        tres[k*2+0] -= modulo
                    tres[k*2+1] += res[j*2+1]
                    if tres[k*2+1] >= modulo:
                        tres[k*2+1] -= modulo
                else:
                    tres[k*2+1] += res[j*2+0]
                    if tres[k*2+1] >= modulo:
                        tres[k*2+1] -= modulo
                    tres[k*2+1] += res[j*2+1]
                    if tres[k*2+1] >= modulo:
                        tres[k*2+1] -= modulo
                k = k+1 if k+1<m else 0
        res = tres
        shift = (shift * 10) % m
    return res[0]


