import sys

def read_address(s):
  result = 0
  base = 1
  for part in reversed(s.split('.')):
    result += int(part) * base
    base *= 256
  return result

def write_address(x):
  parts = 4 * [ None ]
  base = 256
  for i in range(4):
    parts[3 - i] = (x & 255)
    x >>= 8
  return '.'.join(map(str, parts))

