    colour = [0 for i in range(n)]
    ans = 0
    for v in range(n):
        if visited[v]: continue
        stack = [(v, 0)]
        part = [0, 0]
        while stack:
            node, c = stack.pop()
            if not visited[node]:
                part[c] += 1
                visited[node] = True
                colour[node] = c
