def intersect(seqOne, seqTwo):
	seqOne = sorted(seqOne, key=lambda x: x[0])
	seqTwo = sorted(seqTwo, key=lambda x: x[0])
	i = 0
	j = 0
	ans = []
	while i < len(seqOne) and j < len(seqTwo):
		a,b = seqOne[i]
		c,d = seqTwo[j]
		if max(a,c) < min(b,d):
			ans.append( (max(a,c), min(b,d)) )
		if b < d:
			i += 1
		else:
			j += 1
	return ans

