def edge(x, y, n):
    return min(x, y) * n + max(x, y)


def solve():
    n = int(input())
    eqlist, neqlist = [], []
    m = n * n
    edge_adj = [[] for _ in range(m)]
    for i in range(n-1):
        for j, s in enumerate(input().split()):
            for k, c in enumerate(s):
                if c == '1':
                    eqlist.append((i, i+j+1, k))
                    u, v = edge(k, i, n), edge(k, i+j+1, n)
                    edge_adj[u].append(v)
                    edge_adj[v].append(u)
                else:
                    neqlist.append((i, i+j+1, k))

    def check(edges):
        dist = [[n*3]*n for _ in range(n)]
        adj = [[] for _ in range(n)]
        for e in edges:
            u, v = e // n, e % n
            adj[u].append(v)
            adj[v].append(u)
            if u == v:
                return False
        
        for i in range(n):
            dist[i][i] = 0
            stack = [(i, -1, 0)]
            while len(stack) > 0:
                u, par, d = stack.pop()
                for v in adj[u]:
                    if v == par:
                        continue
                    if dist[i][v] < n: # cycle
                        return False
                    dist[i][v] = d + 1
                    stack.append((v, u, d+1))
        
        for i in range(n):
            for j in range(n):
                if dist[i][j] >= n:
                    return False
 
        return all(dist[i][k] == dist[j][k] for i, j, k in eqlist) and\
            all(dist[i][k] != dist[j][k] for i, j, k in neqlist)
    
    edges = None
    vis = [False] * m
    for i in range(m):
        if vis[i]:
            continue
        if i // n > i % n:
            continue

        vis[i] = True
        visited = []
        stack = [i]
        while len(stack) > 0:
            u = stack.pop()
            visited.append(u)
            for v in edge_adj[u]:
                if vis[v]:
                    continue
                vis[v] = True
                stack.append(v)
        
        if len(visited) == n-1 and check(visited):
            edges = visited
            break
    
    if edges is None:
        print('No')
    else:
        print('Yes')
        for e in edges:
            print(e // n + 1, e % n + 1)


