class DSU:
    def __init__(self, limit):
        self.link = [-1]*limit
        self.sz = [1]*limit
        self.even = [False] * limit

    def find(self,u):
        root = u
        par = u
        while par != -1:
            root = par
            par = self.link[par]
         
        par = u
        while par != root:
            self.link[par] = root
            par = self.link[par]
              
        return root
    
    ''' return True if u and v were not in same group, false otherwise '''
    def union(self,u,v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u == root_v:
            return False
        rank_u = self.sz[root_u]
        rank_v = self.sz[root_v]
        if rank_u < rank_v:
            self.link[root_u] = root_v
            self.sz[root_v] += self.sz[root_u]
        else:
            self.link[root_v] = root_u
            self.sz[root_u] += self.sz[root_v]
        return True
    
    ''' return size of the component containing u '''
    def size(self,u):
        return self.sz[self.find(u)]

