import sys

def search(Max,new,num):
	if new[0]>num:
		return 1
	Min =0
	Mid = int((Max+Min)/2)
	while Min<=Max:
		if new[Mid]==num:
			return Mid+1
			break
		elif new[Min]==num:
			return Min+1
			break
		elif new[Mid]<num and new[Mid+1]>num:
			return Mid+2
			break
		elif new[Mid]<num:
			Min=Mid+1
		else:
			Max=Mid-1
		Mid = Min + (Max-Min) //2



